CREATE TABLE IF NOT EXISTS `company_info` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `name` varchar(255) NOT NULL,\n  `phone` varchar(50) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `address` varchar(255) NOT NULL,\n  `slogan` text NOT NULL,\n  `zalo` varchar(50) NOT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\nINSERT INTO `company_info` (`id`, `name`, `phone`, `email`, `address`, `slogan`, `zalo`) VALUES\n(1, 'TEMPLATESBDS', '0919006030', 'contact@templatesbds.com', 'Quận 9, TP. Thủ Đức, TP.HCM', 'Đại đô thị sinh thái Grand Riverside - Không gian sống chuẩn mực quốc tế.', '0919006030');\n\nCREATE TABLE IF NOT EXISTS `projects` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `title` varchar(255) NOT NULL,\n  `slug` varchar(255) NOT NULL,\n  `category` varchar(50) NOT NULL,\n  `categoryLabel` varchar(255) NOT NULL,\n  `price` varchar(50) NOT NULL,\n  `priceNum` float NOT NULL,\n  `area` varchar(50) NOT NULL,\n  `areaNum` float NOT NULL,\n  `bedrooms` int(11) NOT NULL,\n  `bathrooms` int(11) NOT NULL,\n  `direction` varchar(50) NOT NULL,\n  `location` varchar(255) NOT NULL,\n  `zone` varchar(255) NOT NULL,\n  `floor` varchar(50) NOT NULL,\n  `badge` varchar(50) NOT NULL,\n  `image` varchar(255) NOT NULL,\n  `gallery` text NOT NULL,\n  `specs` text NOT NULL,\n  `amenities` text NOT NULL,\n  `desc` text NOT NULL,\n  `highlight` text NOT NULL,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\nINSERT INTO `projects` VALUES (1, 'Căn Hộ 1 Phòng Ngủ Smart Modern (1PN + 1) Tháp Sapphire', 'can-ho-1pn-plus-thap-sapphire', 'can-ho', 'Căn Hộ Cao Cấp', '2.35 Tỷ VNĐ', 2.35, '48.5 m²', 48.5, 1, 1, 'Đông Nam', 'Đại lộ Central Park, Khu Đô Thị Sinh Thái Grand Park', 'Tháp Sapphire S1', 'Tầng 12A', 'BÁN CHẠY', 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=800&q=80', '["https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200&q=80", "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&q=80", "https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80"]', '["Thiết kế 1PN + 1 phòng đa năng thông minh", "Ban công rộng ngắm trực diện công viên sinh thái 12ha", "Cửa kính Low-E cản nhiệt 3 lớp chạm sàn", "Thiết bị vệ sinh Hafele / Kohler cao cấp"]', '["Hồ bơi tràn", "Phòng Gym 3D", "Vườn dạo bộ trên cao", "Smart Home 4.0"]', 'Căn hộ 1PN+1 thiết kế tối ưu công năng, không gian cộng thêm linh hoạt biến đổi thành phòng làm việc hoặc phòng ngủ phụ cho gia đình trẻ.', 'Chiết khấu ngay 8% khi thanh toán sớm — Tặng gói Smart Home 50 triệu');\nINSERT INTO `projects` VALUES (2, 'Căn Hộ 2 Phòng Ngủ Góc Park View (2PN + 2WC) Tháp Ruby', 'can-ho-2pn-goc-parkview-thap-ruby', 'can-ho', 'Căn Hộ Cao Cấp', '3.65 Tỷ VNĐ', 3.65, '72.8 m²', 72.8, 2, 2, 'Nam - Đông Nam', 'Tòa Ruby R2, Grand Park Boulevard', 'Tháp Ruby R2', 'Tầng 18', 'HOT DEAL', 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=800&q=80', '["https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=1200&q=80", "https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=1200&q=80", "https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?w=1200&q=80"]', '["Căn góc 2 mặt thoáng đón gió mát quanh năm", "Bếp riêng khép kín thông thoáng ra logia phơi đồ", "Phòng ngủ Master có phòng thay đồ riêng", "Trang bị hệ thống lọc không khí khử khuẩn tự động"]', '["Sảnh đón 5 sao", "Bãi đỗ xe thông minh", "Sân chơi trẻ em liên hoàn", "Vườn nướng BBQ"]', 'Căn góc 2 phòng ngủ sở hữu tầm nhìn kép tuyệt mỹ ôm trọn biển hồ cảnh quan cát trắng và dải công viên ánh sáng lung linh về đêm.', 'Hỗ trợ lãi suất 0% trong 24 tháng — Ân hạn nợ gốc đến khi nhận nhà');\nINSERT INTO `projects` VALUES (3, 'Căn Hộ 3 Phòng Ngủ Master Luxury Tháp Diamond', 'can-ho-3pn-master-luxury-diamond', 'can-ho', 'Căn Hộ Cao Cấp', '5.20 Tỷ VNĐ', 5.2, '98.6 m²', 98.6, 3, 2, 'Đông', 'Tháp Diamond D1, Mặt tiền Hồ Cảnh Quan', 'Tháp Diamond D1', 'Tầng 22', 'VIP LUXURY', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=800&q=80', '["https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=1200&q=80", "https://images.unsplash.com/photo-1600585154526-990dced4db0d?w=1200&q=80", "https://images.unsplash.com/photo-1600566753376-12c8ab7fb75b?w=1200&q=80"]', '["3 Phòng ngủ rộng rãi với ban công Panorama kéo dài", "Full nội thất nhập khẩu Châu Âu cao cấp", "Khóa cửa vân tay FaceID bảo mật 4 lớp", "Hệ thống nước uống tinh khiết tại vòi chuẩn WHO"]', '["Hồ bơi vô cực trên cao", "Clubhouse thượng lưu", "Sân tập Golf 3D", "Sky Bar Panorama"]', 'Không gian sống hoàn mỹ chuẩn nghỉ dưỡng 5 sao dành riêng cho các gia đình đa thế hệ, mang đến chuẩn mực sống thượng lưu khác biệt.', 'Tặng ngay gói hoàn thiện nội thất 150 triệu — Tặng 3 năm phí quản lý');\nINSERT INTO `projects` VALUES (4, 'Penthouse Sky Villa Duplex Sân Vườn Hoàng Gia', 'penthouse-sky-villa-duplex-hoang-gia', 'can-ho', 'Căn Hộ Cao Cấp', '11.8 Tỷ VNĐ', 11.8, '215.0 m²', 215, 4, 4, 'Đông Nam', 'Tầng 35 Tháp Diamond D1 (Sky Villa)', 'Tháp Diamond Sky', 'Tầng 35-36', 'SIÊU HIẾM', 'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=800&q=80', '["https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=1200&q=80", "https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80", "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&q=80"]', '["Thiết kế Duplex thông tầng trần cao 6.2m cực kỳ bề thế", "Hồ bơi chân mây và sân vườn riêng tại ban công", "Thang máy riêng biệt tận cửa căn hộ", "Tầm view Panorama 360 độ toàn cảnh thành phố"]', '["Thang máy riêng", "Hồ bơi chân mây", "Đỗ xe 2 vị trí định danh", "Quản gia 24/7"]', 'Dinh thự trên không độc bản dành riêng cho 10 vị chủ nhân tinh hoa, khẳng định vị thế đỉnh cao và phong cách sống vương giả.', 'Tặng thẻ VIP đặc quyền Golf Club 10 năm — Chiết khấu thanh toán 12%');\nINSERT INTO `projects` VALUES (5, 'Shophouse Khối Đế Mặt Tiền Đại Lộ 30m Sầm Uất', 'shophouse-khoi-de-dai-lo-30m', 'shophouse', 'Shophouse Thương Mại', '13.5 Tỷ VNĐ', 13.5, '135.0 m²', 135, 2, 3, 'Tây Nam', 'Mặt tiền Đại lộ Grand Boulevard 30m', 'Phân Khu Shophouse', 'Trệt + Lửng (2 Tầng)', 'KINH DOANH ĐẮC ĐỊA', 'https://images.unsplash.com/photo-1577495508048-b635879837f1?w=800&q=80', '["https://images.unsplash.com/photo-1577495508048-b635879837f1?w=1200&q=80", "https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200&q=80"]', '["Mặt tiền kinh doanh 7.5m cực rộng trên đại lộ 30m", "Trần tầng 1 cao 5.8m có lửng thông thoáng", "Phù hợp mở showroom, F&B, ngân hàng, spa cao cấp", "Sở hữu vỉa hè lát đá hoa cương rộng 8m để xe thoải mái"]', '["Vỉa hè 8m", "Phố đi bộ đêm", "Bãi đỗ xe trước cửa", "Hệ thống PCCC tự động"]', 'Tọa lạc tại tuyến phố giao thương sầm uất bậc nhất đại đô thị với lưu lượng hơn 30.000 cư dân qua lại mỗi ngày, bảo chứng sinh lời bền vững.', 'Cam kết thuê lại 8%/năm trong 3 năm đầu — Tặng gói hoàn thiện mặt tiền 100 triệu');\nINSERT INTO `projects` VALUES (6, 'Nhà Phố Vườn Liền Kề Park View 4 Tầng Sang Trọng', 'nha-pho-vuon-lien-ke-park-view-4-tang', 'nha-pho', 'Nhà Phố Liền Kề', '9.8 Tỷ VNĐ', 9.8, '110.0 m²', 110, 4, 5, 'Đông Bắc', 'Phân khu Park Residence, Đường Hoa Ban 16m', 'Phân Khu Nhà Phố', '1 Trệt + 3 Lầu + Sân Thượng', 'MỚI MỞ BÁN', 'https://images.unsplash.com/photo-1512915922686-57c11dde9b6b?w=800&q=80', '["https://images.unsplash.com/photo-1512915922686-57c11dde9b6b?w=1200&q=80", "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&q=80"]', '["Xây dựng 1 trệt 3 lầu + tum sân thượng phong cách tân cổ điển", "Sân trước để ô tô 7 chỗ, sân sau làm tiểu cảnh vườn xanh", "Phòng khách trần cao bề thế, 4 phòng ngủ master khép kín", "Đường trước nhà 16m cây xanh rợp bóng mát"]', '["Sân vườn trước sau", "Gara ô tô", "Hệ thống an ninh 24/7", "Công viên dạo bộ"]', 'Thiết kế thông minh hài hòa giữa không gian sống xanh thanh bình và tiện nghi đô thị hiện đại, nơi chốn an cư lý tưởng vững bền cho nhiều thế hệ.', 'Ân hạn nợ gốc 36 tháng — Nhận ngay 1 cây vàng SJC may mắn');\nINSERT INTO `projects` VALUES (7, 'Biệt Thự Song Lập Hồ Cảnh Quan (Sân Vườn & Hồ Bơi Riêng)', 'biet-thu-song-lap-ho-canh-quan', 'biet-thu', 'Biệt Thự Sinh Thái', '19.5 Tỷ VNĐ', 19.5, '210.0 m²', 210, 4, 5, 'Đông Nam', 'Đảo Ngọc Riverside, Phân khu Biệt thự ven hồ', 'Phân Khu Đảo Biệt Thự', '1 Trệt + 2 Lầu', 'VIEW HỒ 12HA', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=800&q=80', '["https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&q=80", "https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=1200&q=80"]', '["Mặt tiền 10m x Sâu 21m khuôn viên đất vuông vức", "3 Mặt thoáng đón gió tự nhiên từ mặt hồ cảnh quan", "Sân vườn rộng thiết kế sẵn hồ cá Koi và bể bơi riêng biệt", "Pháp lý sổ hồng sở hữu lâu dài vĩnh viễn"]', '["Hồ bơi riêng", "Bến du thuyền nội khu", "Clubhouse ven hồ", "Sân tennis riêng biệt"]', 'Tọa lạc tại bán đảo sinh thái riêng biệt với an ninh đa lớp 24/7, mang đến không gian nghỉ dưỡng thanh bình biệt lập ngay trong lòng đại đô thị.', 'Chiết khấu 10% thanh toán sớm — Tặng gói cảnh quan sân vườn trị giá 200 triệu');\nINSERT INTO `projects` VALUES (8, 'Biệt Thự Đơn Lập Góc Siêu VIP Bến Du Thuyền Riêng', 'biet-thu-don-lap-goc-vip-ben-du-thuyen', 'biet-thu', 'Biệt Thự Sinh Thái', '34.0 Tỷ VNĐ', 34, '360.0 m²', 360, 5, 6, 'Nam', 'Mũi Bán Đảo Hoàng Gia, View Sông Trực Diện', 'Phân Khu Đảo Biệt Thự', '1 Trệt + 2 Lầu + Áp Mái', 'ĐỘC BẢN GIỚI TINH HOA', 'https://images.unsplash.com/photo-1580587771525-78b9dba3b914?w=800&q=80', '["https://images.unsplash.com/photo-1580587771525-78b9dba3b914?w=1200&q=80", "https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80"]', '["Căn góc 2 mặt tiền sông rộng thoáng cực kỳ hiếm có", "Sở hữu bến đỗ du thuyền riêng biệt hợp pháp", "Hồ bơi vô cực tràn bờ mặt nước và phòng xông hơi Sauna riêng", "Hầm rượu vang và rạp chiếu phim gia đình tiêu chuẩn Dolby"]', '["Bến du thuyền", "Hồ bơi tràn viền", "Sân đỗ trực thăng", "Bảo vệ riêng 24/7"]', 'Tuyệt tác dinh thự dành cho các gia tộc danh giá, nơi khẳng định vị thế tôn quý và giá trị tài sản truyền đời qua nhiều thế hệ.', 'Tặng du thuyền thể thao mini hoặc chiết khấu trực tiếp 1.5 Tỷ vào HĐMB');